#!/usr/bin/env bash
set -euo pipefail
# shellcheck source=SCRIPTDIR/../lib/common.sh
source "$(dirname "${BASH_SOURCE[0]}")/../lib/common.sh"
# shellcheck source=SCRIPTDIR/../lib/bitwarden.sh
source "$DOTFILES_ROOT/lib/bitwarden.sh"

# Mirror ~/.ssh into the Bitwarden vault, so `./install.sh ssh-restore` can put
# it back on a new machine. Run it (or the `ssh-backup` shell function) after
# adding a key or editing ~/.ssh/config.
#
# Only top-level regular files are backed up. Skipped: dotfiles,
# known_hosts.old, allowed_signers (regenerated by the ssh step) and
# *.backup.* leftovers. Unchanged files are left alone; items for files that
# no longer exist locally go to the Bitwarden trash, after asking.

ssh_dir="$HOME/.ssh"
[ -d "$ssh_dir" ] || die "$ssh_dir does not exist"

ensure_bw
bw_unlock

step "Backing up $ssh_dir to Bitwarden folder '$BW_SSH_FOLDER'"

mapfile -t files < <(
	find "$ssh_dir" -maxdepth 1 -type f \
		! -name '.*' ! -name 'known_hosts.old' ! -name 'allowed_signers' ! -name '*.backup.*' \
		-printf '%f\n' | sort
)
[ ${#files[@]} -gt 0 ] || die "Nothing to back up in $ssh_dir"

# One file → an array of {name, notes}: a single item, or line-aligned chunks.
# shellcheck disable=SC2016  # jq variables, not shell
chunk_jq='
	[ $content | scan("[^\n]*\n|[^\n]+$") ]
	| reduce .[] as $line ([""];
		if (.[-1] | length) > 0 and (.[-1] | length) + ($line | length) > $max
		then . + [$line] else .[-1] += $line end)
	| length as $n
	| to_entries
	| map({
		name: (if $n == 1 then $file else "\($file) [\(.key + 1)/\($n)]" end),
		notes: .value
	})'

desired="$(
	for file in "${files[@]}"; do
		jq -n --rawfile content "$ssh_dir/$file" --arg file "$file" --argjson max "$BW_CHUNK" "$chunk_jq"
	done | jq -s 'add // []'
)"

folder_id="$(bw_folder_id --create)"
[ -n "$folder_id" ] || die "Could not find or create the '$BW_SSH_FOLDER' folder"
existing="$(bw list items --folderid "$folder_id")"

# Compare what we want with what's there. Only names and ids come out.
# shellcheck disable=SC2016
plan="$(
	{ printf '%s' "$desired"; printf '%s' "$existing"; } | jq -rs '
		.[0] as $want | .[1] as $have
		| ($have | map({key: .name, value: .}) | from_entries) as $h
		| ($want | map(.name)) as $names
		| ($want[] |
			if $h[.name] == null then "create\t\(.name)\t"
			elif ($h[.name].notes // "") == .notes then "same\t\(.name)\t"
			else "update\t\(.name)\t\($h[.name].id)" end),
		  ($have[] | select(.name as $n | any($names[]; . == $n) | not)
			| "stale\t\(.name)\t\(.id)")'
)"

created=0 updated=0 unchanged=0
stale_names=() stale_ids=()

while IFS=$'\t' read -r action name id; do
	case "$action" in
		same) unchanged=$((unchanged + 1)) ;;
		create)
			# shellcheck disable=SC2016
			printf '%s' "$desired" | jq --arg n "$name" --arg f "$folder_id" '
				.[] | select(.name == $n) | {
					organizationId: null, collectionIds: null, folderId: $f,
					type: 2, secureNote: {type: 0}, name, notes,
					favorite: false, fields: [], reprompt: 0
				}' | bw encode | bw create item >/dev/null
			info "added    $name"
			created=$((created + 1))
			;;
		update)
			# shellcheck disable=SC2016
			{ printf '%s' "$desired"; printf '%s' "$existing"; } | jq -s --arg n "$name" --arg id "$id" '
				(.[0][] | select(.name == $n) | .notes) as $notes
				| .[1][] | select(.id == $id) | .notes = $notes' |
				bw encode | bw edit item "$id" >/dev/null
			info "updated  $name"
			updated=$((updated + 1))
			;;
		stale)
			stale_names+=("$name")
			stale_ids+=("$id")
			;;
	esac
done <<<"$plan"

if [ ${#stale_ids[@]} -gt 0 ]; then
	warn "In the vault but not in $ssh_dir:"
	for name in "${stale_names[@]}"; do warn "  $name"; done
	reply=n
	[ -t 0 ] && read -r -p "    Move these to the Bitwarden trash? [y/N] " reply
	if [[ "$reply" =~ ^[Yy]$ ]]; then
		for id in "${stale_ids[@]}"; do bw delete item "$id" >/dev/null; done
		info "Moved ${#stale_ids[@]} item(s) to the trash (recoverable for 30 days)"
	else
		info "Kept them"
	fi
fi

bw sync >/dev/null
info "${#files[@]} file(s): $created added, $updated updated, $unchanged unchanged"
